(function(){
  const KEY='academ-favorites-v1';
  const read=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'[]')}catch{return[]}};
  const write=items=>{localStorage.setItem(KEY,JSON.stringify(items));window.dispatchEvent(new CustomEvent('favorites:change',{detail:items}))};
  const getText=(root,selector,fallback='')=>root?.querySelector(selector)?.textContent.trim()||fallback;
  const itemFor=button=>{const hotel=button.closest('.hotel-result,.hotel-page')||document;const room=button.closest('.room-card,.room-snippet,.room-top,.hotel-offer-widget');const hotelName=getText(hotel,'.hotel-title h2,.hotel-name h1','Москва Красносельская');const roomName=getText(room,'h3','Стандарт двухместный 1 кровать');const price=getText(room,'.offer-price-main strong,.offer-prices strong,.offer-price strong','');const photo=hotel.querySelector('.hotel-photo>img,.hotel-gallery img,.room-photo,.room-snippet>img')?.getAttribute('src')||'assets/hotel-figma/image-3.png';const city=document.querySelector('.search-place input')?.value.trim()||hotelName.split(/\s+/)[0]||'Москва';const dates=getDates();const collectionId=`${city}|${dates}`.toLowerCase().replace(/\s+/g,' ').trim();const collectionTitle=`Город ${city}, Россия, ${dates}`;const id=[hotelName,roomName,price].join('|').toLowerCase().replace(/\s+/g,' ');return{id,hotel:hotelName,room:roomName,price,photo,city,dates,collectionId,collectionTitle,addedAt:new Date().toISOString()}};
  const paint=(button,selected)=>{button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));button.setAttribute('aria-label',selected?'Удалить из подборки':'Добавить в подборку');const img=button.querySelector('img');if(img)img.src=selected?'assets/hotel/heart-fill-new-16.svg':'assets/hotel/heart-new-16.svg'};
  const updateIndicator=()=>document.querySelectorAll('.favorites-count').forEach(badge=>badge.remove());
  const getDates=()=>{const text=getText(document,'.search-date,.searchbar__dates,.search-dates,.date-field','20 дек — 21 дек 2026');const parts=[...text.matchAll(/(\d{1,2})\s+([а-яё]{3})(?:\s+(\d{4}))?/gi)];if(parts.length<2)return'20 дек — 21 дек 2026';const first=parts[0],second=parts[1],year=second[3]||first[3]||'2026';return`${first[1]} ${first[2]} — ${second[1]} ${second[2]} ${year}`};
  let snackbarTimer;
  const showSnackbar=item=>{
    document.querySelector('.favorites-snackbar')?.remove();clearTimeout(snackbarTimer);
    const snackbar=document.createElement('aside');snackbar.className='favorites-snackbar';snackbar.setAttribute('role','status');snackbar.innerHTML=`<span class="favorites-snackbar__heart" aria-hidden="true"><img src="assets/hotel/heart-fill-new-16.svg" alt=""></span><span class="favorites-snackbar__text">Добавлено в подборку<br>${item.city}, ${item.dates}</span><a href="collection-detail.html?collection=${encodeURIComponent(item.collectionId)}">Перейти</a>`;document.body.append(snackbar);
    requestAnimationFrame(()=>snackbar.classList.add('is-visible'));snackbarTimer=setTimeout(()=>{snackbar.classList.remove('is-visible');setTimeout(()=>snackbar.remove(),220)},4500);
  };
  const bind=(root=document)=>root.querySelectorAll('.room-heart,.heart,.offer-favorite').forEach(button=>{if(button.dataset.favoriteBound)return;button.dataset.favoriteBound='1';const item=itemFor(button);paint(button,read().some(x=>x.id===item.id));button.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();const current=read();const exists=current.some(x=>x.id===item.id);write(exists?current.filter(x=>x.id!==item.id):[...current,item]);document.querySelectorAll('.room-heart,.heart,.offer-favorite').forEach(other=>{if(itemFor(other).id===item.id)paint(other,!exists)});if(!exists)showSnackbar(item);updateIndicator()})});
  window.Favorites={read,write,bind,updateIndicator,key:KEY};
  const style=document.createElement('style');style.textContent=`.favorites-snackbar{position:fixed;z-index:6000;left:24px;bottom:24px;display:grid;grid-template-columns:20px minmax(0,1fr) auto;align-items:center;gap:12px;width:min(388px,calc(100vw - 48px));min-height:80px;padding:12px 20px;border-radius:24px;color:#fff;background:linear-gradient(105deg,rgba(92,92,95,.96),rgba(70,70,73,.96));box-shadow:0 12px 32px rgba(0,0,0,.2);font:400 16px/20px "YS Text",Arial,sans-serif;opacity:0;transform:translateY(16px);transition:opacity .2s ease,transform .2s ease;backdrop-filter:blur(40px)}.favorites-snackbar.is-visible{opacity:1;transform:translateY(0)}.favorites-snackbar__heart{display:grid;width:20px;height:20px;min-width:20px;place-items:center}.favorites-snackbar__heart img{display:block;width:16px!important;height:16px!important;min-width:16px;object-fit:contain;filter:brightness(0) invert(1)}.favorites-snackbar__text{min-width:0}.favorites-snackbar a{display:grid;height:40px;padding:0 16px;place-items:center;border-radius:14px;background:#222125;color:#fff;font:500 14px/18px "YS Text",Arial,sans-serif;text-decoration:none}@media(max-width:600px){.favorites-snackbar{left:12px;bottom:12px;width:calc(100vw - 24px)}}`;document.head.append(style);
  document.addEventListener('DOMContentLoaded',()=>{bind();updateIndicator()});window.addEventListener('favorites:change',updateIndicator);
})();
